ALTER TABLE "ProviderProfile" ADD COLUMN "latitude" DOUBLE PRECISION, ADD COLUMN "longitude" DOUBLE PRECISION, ADD COLUMN "serviceRadiusKm" DOUBLE PRECISION NOT NULL DEFAULT 10, ADD COLUMN "available" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "ServiceRequest" ADD COLUMN "customerTrackingEnabled" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "providerTrackingEnabled" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "providerTravelStartedAt" TIMESTAMP(3), ADD COLUMN "providerArrivedAt" TIMESTAMP(3), ADD COLUMN "workStartedAt" TIMESTAMP(3), ADD COLUMN "completedAt" TIMESTAMP(3), ADD COLUMN "trackingEndedAt" TIMESTAMP(3);
CREATE TABLE "RequestLocation" ("id" TEXT NOT NULL,"requestId" TEXT NOT NULL,"userId" TEXT NOT NULL,"latitude" DOUBLE PRECISION NOT NULL,"longitude" DOUBLE PRECISION NOT NULL,"accuracyMeters" DOUBLE PRECISION,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RequestLocation_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "RequestLocation_requestId_userId_key" ON "RequestLocation"("requestId","userId"); CREATE INDEX "RequestLocation_requestId_updatedAt_idx" ON "RequestLocation"("requestId","updatedAt");
ALTER TABLE "RequestLocation" ADD CONSTRAINT "RequestLocation_requestId_fkey" FOREIGN KEY ("requestId") REFERENCES "ServiceRequest"("id") ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT "RequestLocation_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
